const endereco = String($input.first().json.endereco_quadro || '').trim();
const partes = /^https:\/\/trello\.com\/b\/([A-Za-z0-9]{8})(?:[/?#]|$)/.exec(endereco);
if (!partes) throw new Error('Cole o endereço da barra do navegador com o seu quadro aberto em trello.com/b/.');
return [{ json: { codigo: partes[1] } }];

const quadro = $input.first().json;
if (quadro.name !== 'Orbita Labs · Diagnósticos' || quadro.prefs?.permissionLevel !== 'private') {
  throw new Error('Use um quadro novo e privado com o nome Orbita Labs · Diagnósticos.');
}
if (![quadro.lists, quadro.labels, quadro.cards].every(Array.isArray)) {
  throw new Error('A consulta precisa devolver listas, etiquetas e cartões. Confira o nó Ler quadro.');
}
const etapas = ["Novo lead","Contato feito","Diagnóstico agendado","Proposta","Fechado"];
const cores = { quente: 'red', morno: 'yellow', frio: 'blue' };
const exemplos = [
  {
    "nome": "Ateliê de Papel · Bia Luz",
    "email": "bia@atelie.example",
