    "nota": 50,
    "faixa": "morno",
    "etapa": "Fechado"
  }
];

const listasExtras = quadro.lists.filter(lista => !etapas.includes(lista.name));
if (listasExtras.length) {
  throw new Error('O quadro contém outras listas. Se forem as listas iniciais vazias do quadro novo, arquive-as no Trello e execute de novo.');
}
function identificar(itens, nome) {
  const encontrados = itens.filter(item => item.name === nome);
  if (encontrados.length > 1) throw new Error('Há nomes repetidos no quadro: ' + nome);
  return encontrados[0];
}
function criar(caminho, parametros) {
  // O quadro pode ter ficado pronto entre duas execuções. Leia-o antes de cada escrita.
  if ($runIndex >= 16) throw new Error('O quadro não refletiu as últimas mudanças. Confira o Trello e inicie novamente.');
  return [{ json: { pronto: false, caminho, parametros } }];
}
for (const [indice, etapa] of etapas.entries()) {
  if (!identificar(quadro.lists, etapa)) {
    return criar('boards/' + quadro.id + '/lists', { name: etapa, pos: String((indice + 1) * 65536) });
  }
}
for (const [faixa, cor] of Object.entries(cores)) {
  if (!identificar(quadro.labels, faixa)) {
    return criar('boards/' + quadro.id + '/labels', { name: faixa, color: cor });
  }
}
for (const exemplo of exemplos) {
  if (identificar(quadro.cards, exemplo.nome)) continue;
  const descricao = [
    'Exemplo fictício da Orbita Labs.',
    'E-mail: ' + exemplo.email, 'WhatsApp: ' + (exemplo.whatsapp || 'não informado'),
    'Porte: ' + exemplo.porte, 'Área: ' + exemplo.area, 'Prazo: ' + exemplo.prazo,
    'Nota: ' + exemplo.nota, 'Faixa: ' + exemplo.faixa,
  ].join('\n');
  return criar('cards', {
    name: exemplo.nome,
    desc: descricao,
    idList: identificar(quadro.lists, exemplo.etapa).id,
    idLabels: identificar(quadro.labels, exemplo.faixa).id,
  });
}
return [{ json: {
  pronto: true,
  quadro: quadro.url,
  lista_novo_lead: identificar(quadro.lists, 'Novo lead').id,
  etiqueta_quente: identificar(quadro.labels, 'quente').id,
  etiqueta_morno: identificar(quadro.labels, 'morno').id,
  etiqueta_frio: identificar(quadro.labels, 'frio').id,
} }];
